// Build search URLs for the niche across several public sources.
// Tip: for reliable Google results, add a SerpAPI/Bing-API node instead of
// scraping (search engines block bots / Cloudflare). These are examples.
const body = $input.first().json.body || $input.first().json.query || {};
const niche = (body.niche || 'crypto').toString();
const user_id = Number(body.user_id || 0);
const q = encodeURIComponent(niche);
const qg = encodeURIComponent('"' + niche + '" telegram group t.me');
const urls = [
  // Search engines (swap for an official search API where possible)
  `https://www.bing.com/search?q=${qg}&count=40`,
  `https://html.duckduckgo.com/html/?q=${qg}`,
  // Telegram group directories (public listing sites)
  `https://lyzem.com/search?q=${q}&type=groups`,
  `https://tgstat.com/search?q=${q}`,
  `https://cse.google.com/cse?cx=&q=${qg}`
];
return urls.map(u => ({ json: { url: u, niche, user_id } }));

// Extract t.me/<username> links from every fetched page, dedupe, shape docs.
const bad = new Set(['joinchat','share','addstickers','addemoji','proxy','socks','iv','s','c','setlanguage','login','bg']);
const seen = new Set();
const out = [];
const re = /t\.me\/([A-Za-z0-9_]{4,32})/g;
for (const item of $input.all()) {
  const body = String(item.json.data || item.json.body || item.json.body?.data || '');
  const niche = item.json.niche || '';
  const user_id = Number(item.json.user_id || 0);
  let m;
  while ((m = re.exec(body)) !== null) {
    const u = m[1];
    const ul = u.toLowerCase();
    if (bad.has(ul) || ul.endsWith('bot') || seen.has(ul)) continue;
    seen.add(ul);
    out.push({ json: { username: u, niche, user_id, source: 'web', discovered_at: new Date().toISOString() } });
  }
}
return out;
